package com.rumitx.app;
import android.app.*;import android.widget.*;import android.text.InputType;
public final class IdentityDialog {
 public static void show(Activity a,Runnable changed){LinearLayout body=new LinearLayout(a);body.setOrientation(1);body.setPadding(24,16,24,16);body.setBackgroundColor(0xff050508);EditText name=new EditText(a),id=new EditText(a);name.setHint("Radio Name / Callsign");name.setSingleLine(true);name.setText(DmrIdentity.name(a));id.setHint("DMR ID (numeric)");id.setInputType(InputType.TYPE_CLASS_NUMBER);id.setText(DmrIdentity.id(a));name.setMinHeight(48);id.setMinHeight(48);body.addView(name);body.addView(id);TextView note=new TextView(a);note.setTextColor(0xffb5dae6);note.setText("DMR ID is applied with digital channel programming. Callsign is stored locally; the module name command is unverified.");body.addView(note);AlertDialog d=new AlertDialog.Builder(a).setTitle("DMR Identity").setView(body).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(b->{try{DmrIdentity.save(a,name.getText().toString(),id.getText().toString());changed.run();d.dismiss();}catch(IllegalArgumentException e){id.setError(e.getMessage());}}));d.show();}
}
